/**
 * Everything the engine needs for one frame. The shell collects plane
 * add/update/remove events, the camera pose, and the spray-button state and
 * calls `Engine::tick` once per rendered frame.
 */
public struct FrameInputF: Equatable, Hashable {
    /**
     * Camera world position.
     */
    public var cameraPosition: Vec3F
    /**
     * Center-of-view ray (the "spray nozzle"): origin + unit direction.
     * Normally the camera position and forward vector.
     */
    public var rayOrigin: Vec3F
    public var rayDir: Vec3F
    /**
     * Plane anchors added or updated since the last tick.
     */
    public var planeUpserts: [PlaneObservationF]
    /**
     * Plane anchor ids removed since the last tick.
     */
    public var planeRemovals: [UInt64]
    /**
     * Scene-depth sample at screen center in meters (LiDAR devices only).
     */
    public var lidarCenterDepthM: Float?
    public var tracking: TrackingStateF
    /**
     * True while the user holds the spray button.
     */
    public var spraying: Bool
    /**
     * Frame delta time, seconds. Drives hand-speed thinning, dwell
     * stamping and can-shake decay. 0 is treated as ~1/60 s.
     */
    public var dtSeconds: Float

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * Camera world position.
         */cameraPosition: Vec3F,
        /**
         * Center-of-view ray (the "spray nozzle"): origin + unit direction.
         * Normally the camera position and forward vector.
         */rayOrigin: Vec3F, rayDir: Vec3F,
        /**
         * Plane anchors added or updated since the last tick.
         */planeUpserts: [PlaneObservationF],
        /**
         * Plane anchor ids removed since the last tick.
         */planeRemovals: [UInt64],
        /**
         * Scene-depth sample at screen center in meters (LiDAR devices only).
         */lidarCenterDepthM: Float?, tracking: TrackingStateF,
        /**
         * True while the user holds the spray button.
         */spraying: Bool,
        /**
         * Frame delta time, seconds. Drives hand-speed thinning, dwell
         * stamping and can-shake decay. 0 is treated as ~1/60 s.
         */dtSeconds: Float) {
        self.cameraPosition = cameraPosition
        self.rayOrigin = rayOrigin
        self.rayDir = rayDir
        self.planeUpserts = planeUpserts
        self.planeRemovals = planeRemovals
        self.lidarCenterDepthM = lidarCenterDepthM
        self.tracking = tracking
        self.spraying = spraying
        self.dtSeconds = dtSeconds
    }




}

